MM.mnemo[25] = {"cards":[{"id":"ko-k3-0432","w":"어울리다","cs":"slušet, hodit se","en":"to suit, to go well with (잘 어울리다 = to suit someone well)","p":"v","o":"k","ex":"잘 어울리네요.","exc":"Moc ti to sluší!","m":"Základ „spojit se dohromady“: věc ti „sedne“. 그 옷이 잘 어울려요 = to oblečení ti sluší. S lidmi = stýkat se (친구들과 어울리다).","tv":["어울려요","어울렸어요"]},{"id":"ko-k3-0433","w":"맞다","cs":"mít pravdu; být správný; sedět","en":"to be correct, to be right","p":"v","o":"k","ex":"맞네요.","exc":"Aha, máš pravdu!","m":"맞아요! = Přesně tak! 답이 맞다 = odpověď je správná, 옷이 맞다 = oblečení padne. Opak 틀리다 (být špatně).","tv":["맞아요","맞았어요"]},{"id":"ko-k3-0434","w":"깊다","cs":"hluboký","en":"to be deep","p":"a","o":"k","ex":"물이 생각보다 깊네요.","exc":"Ta voda je hlubší, než jsem čekal! (이 → 1. pád; 보다 → než)","m":"Vyslovuje se [깁따], před samohláskou zní ㅍ → 깊어요 [기퍼요]. Používá se i přeneseně: 깊은 밤 (hluboká noc), 깊은 생각 (hluboká myšlenka). Opak: 얕다 (mělký).","tv":["깊어요","깊었어요"]},{"id":"ko-k3-0435","w":"더럽다","cs":"špinavý; ušpiněný","en":"to be dirty","p":"a","o":"k","ex":"제 방은 항상 더럽네요.","exc":"Můj pokoj je pořád tak špinavý! (은 → téma)","m":"Nepravidelné časování s ㅂ → 더러워요 (je špinavý). Opak: 깨끗하다 (čistý).","tv":["더러워요","더러웠어요"],"irr":"ㅂ"},{"id":"ko-k3-0436","w":"밝다","cs":"světlý; jasný; veselý (povaha)","en":"to be bright","p":"a","o":"k","ex":"지금 밤 10시인데 아직도 밝네요.","exc":"Teď je deset večer a pořád je ještě světlo!","m":"Pozor na výslovnost složené koncovky ㄺ: před souhláskou zní jako ㄱ → 밝네요 [방네요], 밝다 [박따], ale před samohláskou zní obojí → 밝아요 [발가요]. Opak: 어둡다 (tmavý).","tv":["밝아요","밝았어요"]},{"id":"ko-k3-0437","w":"남편","cs":"manžel","en":"husband","p":"n","o":"s","ex":"좋은 남편이네요.","exc":"To je ale hodný manžel!","m":"男 muž + 便 strana, blízký = manžel (doslova ‚muž po mém boku‘). Stejné 男 znáš ze slov 남자 (muž) a 남동생 (mladší bratr). Opak: 아내 (manželka).","r":["nam-男","pyeon-便"]},{"id":"ko-k3-0439","w":"항상","cs":"vždy; pořád; neustále","en":"always, all the time","p":"o","o":"s","ex":"제 방은 항상 더럽네요.","exc":"Můj pokoj je pořád tak špinavý! (은 → téma)","m":"恒 stálý, trvalý + 常 stálý, obvyklý = vždy, pořád. Synonymem v hovorové korejštině je ryze korejské 늘 nebo 언제나.","r":["hang-恒","sang-常"]},{"id":"ko-k3-0440","w":"밤","cs":"noc; večer","en":"night","p":"n","o":"k","ex":"지금 밤 10시인데 아직도 밝네요.","exc":"Teď je deset večer a pořád je ještě světlo!","m":"Častá spojení: 오늘 밤 (dnes v noci), 밤늦게 (pozdě v noci), 밤을 새우다 (probdít celou noc). Pozor na homonymum 밤 = jedlý kaštan."},{"id":"ko-k3-0441","w":"아무도","cs":"nikdo (se záporem)","en":"nobody (+ negative)","p":"o","o":"k","ex":"아무도 안 왔네요.","exc":"Aha, nikdo ještě nepřišel.","m":"아무 (kdokoliv) + -도 (ani, i) se záporem znamená ‚nikdo‘ (doslova ‚ani kdokoliv‘): 아무도 없어요 = Nikdo tu není. Kladně se používá 아무나 = kdokoliv."},{"id":"ko-k3-0442","w":"드라마","cs":"seriál; televizní drama","en":"drama (TV series)","p":"n","o":"e","ex":"이 드라마 재미있네요.","exc":"Tenhle seriál je docela zábavný!","m":"Výpůjčka z anglického ‚drama‘ – v korejštině označuje jakýkoli televizní seriál (nejen dramatický žánr). 한국 드라마 (zkráceně 한드) = korejský seriál."},{"id":"ko-k3-0443","w":"집안일","cs":"domácí práce","en":"housework","p":"n","o":"k","ex":"집안일 하는 거 힘들지 않아요?","exc":"Není to náročné dělat domácí práce?","m":"집 dům + 안 vnitřek + 일 práce = práce uvnitř domu. 집안일을 하다 = dělat domácí práce."},{"id":"ko-k3-0444","w":"생각보다","cs":"než jsem myslel; nad očekávání","en":"than I thought","p":"o","o":"k","ex":"물이 생각보다 깊네요.","exc":"Ta voda je hlubší, než jsem čekal! (이 → 1. pád; 보다 → než)","m":"생각 (myšlenka, pomyšlení) + -보다 (částice pro srovnání ‚než‘) = ‚než jsem si myslel‘. Častá vazba: 생각보다 쉽다 = být lehčí, než jsem čekal."}],"gram":{"id":"ko-k3-g25","w":"-네요","en":"Verb ending -네요","cs":"páni, to je ale…; vidím, že… (překvapení, nové zjištění)","vy":"Koncovka -네요 se připojuje přímo ke kmeni slovesa nebo přídavného jména bez ohledu na to, zda končí samohláskou, nebo souhláskou (u kmenů na ㄹ toto ㄹ odpadá, např. 알다 → 아네요). Vyjadřuje okamžité překvapení, obdiv nebo zjištění něčeho nového na základě vlastní zkušenosti v danou chvíli (‚páni, to je ale…‘, ‚aha, ono to…‘). U podstatných jmen se sponou 이다 má tvar -이네요 (po souhlásce) nebo -네요 (po samohlásce).","m":"Rozdíl oproti prostému -어요: 맛있어요 jen suše konstatuje fakt (‚je to dobré‘), zatímco 맛있네요 vyjadřuje bezprostřední reakci po prvním soustu (‚páni, to je ale výborné!‘). Před -네요 se u kmenů na ㄹ toto ㄹ vypouští (멀다 → 머네요).","s":[["맛있어요. · 맛있네요.","Je to dobré. (konstatování faktu) · Páni, to je ale dobré! (překvapení, obdiv)"],["크 + 네요 → 크네요.","Páni, to je ale velké! (vyjádření překvapení u slovesa 크다)"],["잘 어울리네요.","Moc ti to sluší!"],["맞네요.","Aha, máš pravdu! / Ono to sedí!"],["여기 있네요!","Jé, tady to je!"],["이 드라마 재미있네요.","Tenhle seriál je fakt zábavný!"],["별로 안 춥네요.","No, není až taková zima."],["아무도 안 왔네요.","Aha, ještě tu nikdo není."],["벌써 11월이네요.","Páni, už je listopad!"],["집안일 하는 거 힘들지 않아요?","Není to náročné dělat domácí práce?"],["힘들어요. 그래도 남편이 많이 도와줘요.","Je to náročné, ale manžel mi hodně pomáhá."],["오, 그래요? 좋은 남편이네요.","Vážně? To je ale hodný manžel!"],["시험이 너무 어렵네요.","Ta zkouška je strašně těžká!"],["가방이 진짜 무겁네요.","Ta taška je fakt těžká!"],["물이 생각보다 깊네요.","Ta voda je hlubší, než jsem si myslel!"],["지금 밤 10시인데 아직도 밝네요.","Už je deset večer, a pořád je světlo!"],["석진 씨, 빨리 왔네요.","Sokdžine, přišel jsi ale brzy!"]]}};
